interface Component { long size(); }              # operations valid for every node
class Leaf implements Component { ... }              # no children: does the real work
class Composite implements Component {
    private final List<Component> children = new ArrayList<>();
    void add(Component c) { children.add(c); }        # child management stays here
    public long size() { long s = 0; for (Component c : children) s += c.size(); return s; }
}
